import csv

with open('csv/trans.csv', 'r') as f:
    reader = csv.DictReader(f)
    operations = set()
    for row in reader:
        operations.add(row['operation'])

print('All distinct operations:')
for op in sorted(operations):
    print(f'  {op}')

print('\nLooking for withdrawal-related operations...')
for op in sorted(operations):
    if 'vych' in op.lower() or 'vyd' in op.lower() or 'odber' in op.lower():
        print(f'  {op}')

